import subprocess,time,resource,statistics,json,sys
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'))
from validation_support import clean_environment
w=Path('/tmp/birnam-runtime-audit-20261019');prefixes={'baseline':Path('/tmp/birnam-candidate-policy/compact-prefix'),'memory':w/'prefix-memory'}
env=clean_environment();env['BIRNAM_GC_PRECISE']='1';rows=[]
def run(n,script):
 before=resource.getrusage(resource.RUSAGE_CHILDREN);start=time.perf_counter();p=subprocess.run([prefixes[n]/'bin/birnam',script],env=env,capture_output=True,text=True,timeout=60);wall=time.perf_counter()-start;after=resource.getrusage(resource.RUSAGE_CHILDREN)
 assert p.returncode==0 and p.stdout=='ready\n' and not p.stderr,(n,p)
 return dict(wall_seconds=wall,cpu_seconds=after.ru_utime+after.ru_stime-before.ru_utime-before.ru_stime)
for mode,script in [('startup_script',w/'ready.birnam'),('saved_image',w/'no-temp.image')]:
 for n in prefixes:run(n,script)
 for i in range(5):
  for n in (['baseline','memory'] if i%2==0 else ['memory','baseline']):
   rows.append(dict(mode=mode,variant=n,repeat=i,**run(n,script)))
  (w/'memory-startup-comparison.json').write_text(json.dumps({'rows':rows},indent=2)+'\n');print(mode,i+1,flush=True)
medians={m:{n:{k:statistics.median(r[k] for r in rows if r['variant']==n and r['mode']==m) for k in ['wall_seconds','cpu_seconds']} for n in prefixes} for m in ['startup_script','saved_image']}
(w/'memory-startup-comparison.json').write_text(json.dumps({'rows':rows,'medians':medians,'scope':'Five interleaved fresh processes after one warmup per variant/workload; precise GC and identical preexisting authored artifacts/images; diagnostic native overlay only. Background user workloads active.'},indent=2)+'\n')
print(json.dumps(medians,indent=2),flush=True)
